'use strict';
(()=>{
const app=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US');
const label=v=>({awaiting_buyer:'Waiting for buyer',awaiting_payment:'Ready to pay',collection_pending:'Checking payment',held:'Payment held',delivered:'Ready to check',release_pending:'Release requested',payout_pending:'Payment received · payout pending',completed:'Recipient paid',disputed:'Release paused',payout_failed:'Payment received · needs attention',payout_unknown:'Payment received · checking payout',refund_pending:'Refund requested',refunded:'Refunded',payment_failed:'Payment unsuccessful',open:'Ready to share',settled:'Settlement completed',settlement_pending:'Settlement in progress',settlement_attention:'Settlement needs attention',review_required:'Payment received · review required',expired:'Expired'})[v]||String(v||'').replaceAll('_',' ');
const fee=n=>Math.max(100,Math.ceil(n*.02));
const date=n=>new Date(n*1000).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Rangoon'});
const key=()=>crypto.randomUUID();
let session=null,current=null,adminData=null,routeSequence=0,poll=null,busy=false;
let createDraft=null;
try{createDraft=JSON.parse(sessionStorage.getItem('handshake-review-draft')||'null');}catch{}
const reduceMotion=new URLSearchParams(location.search).get('motion')==='reduce';
let backup=sessionStorage.getItem('handshake-new-recovery')||'';
let adminFilter='attention',search='',queueAssignee='',queueMinAmount=0,queueAge=0,draftTimer;
const canFinance=()=>['finance','admin'].includes(session?.role);
function statusMascot(r,state){const id=(r.events||[]).filter(e=>/collection.confirmed|payout.confirmed|refund.confirmed/.test(e.type)).at(-1)?.id;const token='handshake-motion-'+(session?.actor||'public')+'-'+r.id+'-'+id;const celebratory=['payment_confirmed','payout_confirmed'].includes(state);if(celebratory&&sessionStorage.getItem(token))state='idle';else if(celebratory)sessionStorage.setItem(token,'seen');return mascot(state);}
async function api(path,body){const response=await fetch(path,{credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-Handshake':'1'}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'This action could not be completed.');return data;}
function toast(message){document.getElementById('toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.getElementById('toast').textContent='',4500);}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
function button(text,action,cls='primary',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function link(text,route,cls='quiet'){return `<a class="${cls}" href="#${route}">${text}</a>`;}
function head(title,back='home'){return `<div class="page-head"><a class="back" href="#${back}" aria-label="Back">‹</a><h1>${title}</h1></div>`;}
function top(title){return `<div class="topline"><span class="eyebrow">${title}</span><a class="pill" href="#access">${session?.role==='customer'?'Private session':session?'Staff · '+esc(session.actor):'Restore access'} <span aria-hidden="true">&nbsp;↗</span></a></div>`;}
function rows(items){return `<div class="rows">${items.map(([k,v])=>`<div class="row"><span>${k}</span><b>${v}</b></div>`).join('')}</div>`;}
function amount(n,caption=''){return `<div class="amount">${fmt(n)}<small>MMK</small>${caption?`<span class="caption">${caption}</span>`:''}</div>`;}
function mascot(state='greeting'){return `<soft-elephant state="${state}"></soft-elephant>`;}
function beneficiary(r){return `<div class="recipient"><div class="avatar">${esc((r.name||'H')[0])}</div><div><b>${esc(r.name)}</b><small>${esc(r.rail)} ${esc(r.destination_mask||'')} · simulated destination</small></div></div>`;}
function errorBox(){return '<div id="error" class="error" role="alert" tabindex="-1"></div>';}
function showError(message){const e=document.getElementById('error');if(e){e.textContent=message;e.focus?.();}else toast(message);}
function backupBanner(){return backup?`<div class="backup"><b>Keep your private access.</b><p>This key restores your activity on another browser. Keep it separate from public payment links.</p><code>${esc(backup)}</code><button class="text-link" data-action="download-key">Save recovery key</button><button class="text-link" data-action="dismiss-backup">I saved it</button></div>`:'';}
async function customer(){if(session?.role==='customer')return;if(session)throw new Error('Sign out of the staff session before acting as a customer.');const result=await api('/api/session/create',{});session=result.session;backup=result.recovery;sessionStorage.setItem('handshake-new-recovery',backup);}
function activityRows(records){if(!records.length)return `<div class="empty"><h3>Your next step starts here.</h3><p>Create a protected deal or payment request. Its progress will appear here.</p></div>`;return records.map(r=>`<a class="activity-row" href="#record/${r.id}"><span class="avatar">${r.kind==='escrow'?'↔':r.kind==='shop'?'⌂':'↗'}</span><span><b>${esc(r.item||r.name)}</b><small>${r.kind==='escrow'?'Protected deal':r.kind==='shop'?'Shop payment page':r.kind==='request'?'Payment request':'Customer payment'} · ${esc(r.code)}</small></span><span class="right"><b>${r.kind==='shop'?'Permanent QR':fmt(r.net)+' MMK'}</b><small>${r.kind==='shop'?(r.paused?'Paused':'Accepting payments'):label(r.state)}</small></span></a>`).join('');}
async function home(seq){const data=session?.role==='customer'?await api('/api/activity'):{records:[]};if(seq!==routeSequence)return;const visible=data.records.filter(r=>r.kind!=='payment'||!data.records.some(x=>x.id===r.source_id));app.innerHTML=top('A little more peace of mind')+backupBanner()+`<section data-screen-label="Home"><div class="greeting"><div><h1>Good things start<br>with a handshake.</h1><p>Protect a deal. Accept a payment.<br>Keep everything in one place.</p></div>${mascot()}</div><div class="services"><a class="service escrow" href="#create/escrow"><div class="service-icon" aria-hidden="true">↔</div><h2>Protect a deal</h2><p>Hold a buyer’s payment until they receive and check what you agreed.</p><div class="service-link">Create an escrow <span aria-hidden="true">↗</span></div></a><a class="service" href="#create/request"><div class="service-icon" aria-hidden="true">↗</div><h2>Accept a payment</h2><p>Share one request. Let your customer pay with a supported bank or wallet.</p><div class="service-link">Create a request <span aria-hidden="true">↗</span></div></a></div><div class="shop-shortcut"><div><b>One QR for your shop.</b><p>A permanent payment page for every customer.</p></div><a class="pill" href="#create/shop">Set up shop &nbsp;↗</a></div><div class="section-heading"><h2>Your recent activity</h2><a class="text-link" href="#activity">View all &nbsp;↗</a></div>${activityRows(visible.slice(0,4))}<div class="section-heading"><a class="text-link" href="#help">How Handshake works</a><a class="text-link" href="#admin">Staff workspace</a></div></section>`;}
function field(name,title,value='',type='text',extra=''){return `<label class="field"><span>${title}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(name,title,options,value){return `<label class="field"><span>${title}</span><select name="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;}
function draftFor(kind){try{const stored=JSON.parse(localStorage.getItem('handshake-draft-'+kind));if(stored)return stored;}catch{}return {kind,name:'',net:'',rail:'KPay',destination:'',item:'',description:'',delivery:'',window:'24 hours after confirmed receipt'};}
function create(kind){if(!['escrow','request','shop'].includes(kind))throw new Error('Choose one of the two services from Home.');const d=draftFor(kind);createDraft=d;const title=kind==='escrow'?'Create a protected deal':kind==='shop'?'Set up your shop':'Create a payment request';app.innerHTML=top('Make it yours')+head(title)+backupBanner()+`<section class="form-card" data-screen-label="${title}"><span class="eyebrow">${kind==='shop'?'Permanent payment page':kind==='escrow'?'Escrow · seller setup':'One request · one payment'}</span><h2 class="subheading">${kind==='shop'?'Your shop. One simple QR.':kind==='escrow'?'Agree first. Pay with confidence.':'What should you receive?'}</h2><form id="create-form" data-kind="${kind}">${field('name',kind==='shop'?'Shop name':'Your name',d.name,'text','required maxlength="60" autocomplete="name"')}${kind==='escrow'?`${field('item','Item or service',d.item,'text','required maxlength="100"')}<label class="field"><span>Short description</span><textarea name="description" maxlength="600" required>${esc(d.description)}</textarea></label>${field('delivery','How and when will you deliver?',d.delivery,'text','required maxlength="300"')}${field('window','Time for the buyer to check',d.window,'text','required maxlength="100"')}`:''}${kind!=='shop'?field('net',kind==='escrow'?'Item amount · MMK':'You receive · MMK',d.net,'number','required min="500" max="1000000" step="1" inputmode="numeric"'):''}${selectField('rail','Receive through',['KPay','WavePay','UAB Pay','AYA Pay'],d.rail)}${field('destination','Demo payout phone or account',d.destination,'text','required minlength="5" maxlength="30" autocomplete="off"')}<label class="check"><input name="demo_verified" type="checkbox" required><span>Use this as a simulated verified destination. No real account is connected.</span></label>${errorBox()}<div class="actions"><button class="primary" type="submit">Review ${kind==='shop'?'shop':'details'} &nbsp;→</button></div><p class="fine">${kind==='shop'?'Every customer enters an amount and creates their own payment.':kind==='request'?'Requests expire after 30 minutes. Quotes last 15 minutes.':'The buyer checks delivery and authorizes release. A report pauses release.'} Your unfinished form is saved on this browser.</p></form></section>`;}
function review(){if(!createDraft)return go('home');const d=createDraft;app.innerHTML=top('One last look')+head('Review '+(d.kind==='shop'?'shop':'details'),'create/'+d.kind)+`<section class="flow-card" data-screen-label="Review creation"><h1>${d.kind==='shop'?'Ready for every customer.':'Ready to share.'}</h1>${d.kind!=='shop'?amount(d.net,d.kind==='escrow'?'Seller receives':'You receive'):mascot('waiting')}${beneficiary({...d,destination_mask:'•• '+d.destination.slice(-4)})}${rows([...(d.kind==='escrow'?[['Item',esc(d.item)],['Delivery',esc(d.delivery)],['Check window',esc(d.window)]]:[]),...(d.kind!=='shop'?[['Customer pays',fmt(d.net+fee(d.net))+' MMK'],['Illustrative fee',fmt(fee(d.net))+' MMK']]:[['Payment page','Permanent · customer enters amount']]),['Settlement','Simulated; confirmed separately']])}${errorBox()}<div class="actions">${button(d.kind==='shop'?'Create shop page':d.kind==='escrow'?'Create protected deal':'Create payment request','create-confirm')}${link('Edit details','create/'+d.kind)}</div></section>`;}
function share(r){const url=location.origin+'/#record/'+r.id;app.innerHTML=top('Ready when they are')+head(r.kind==='shop'?'Your shop QR':'Share your '+(r.kind==='escrow'?'deal':'request'))+backupBanner()+`<section class="flow-card" data-screen-label="Share link"><div class="hero">${mascot('request_created')}<h1>${r.kind==='shop'?'One QR. Every customer.':'Send a little confidence.'}</h1><p>${esc(r.name)}${r.net?' · '+fmt(r.net)+' MMK':''}</p></div>${r.kind==='escrow'?`<div class="note"><b>Buyer invitation key · share privately</b><div class="link-box">${esc(r.invitation)}</div><p>Give this key to your intended buyer separately. The public link only opens the review.</p></div>`:''}<img class="qr" src="/api/qr?text=${encodeURIComponent(url)}" alt="QR code for this browser payment page"><p class="code">${esc(r.code)}</p><p class="fine">Scan with a camera to open in a browser. This is not a bank-app payment QR.</p><div class="link-box">${esc(url)}</div>${r.kind==='request'?`<p class="fine">Expires ${date(r.expires)} · one successful payment</p>`:''}${errorBox()}<div class="actions">${button('Copy public link','copy','primary',`data-value="${esc(url)}"`)}${link('Open '+(r.kind==='shop'?'shop page':'public page'),'record/'+r.id)}${link('Your activity','activity')}</div><p class="fine">${r.kind==='escrow'?'To try the buyer side, open this link in a private browser window. ':''}This local address works on this computer. Private recovery keys stay separate.</p></section>`;}
function settlementSummary(r){return r.settlement_legs?`<div class="timeline">${r.settlement_legs.map(leg=>`<div class="step ${leg.payout==='confirmed'?'done':'current'}"><span class="node">${leg.payout==='confirmed'?'✓':'·'}</span><div><b>${leg.instruction_type==='refund'?'Buyer refund':'Seller payout'} · ${fmt(leg.net)} MMK</b><small>${label(leg.state)}</small>${session?.role!=='customer'?link('Follow this instruction','case/'+leg.id):''}</div></div>`).join('')}</div>`:'';}
function splitConsent(r){const t=r.split_terms;if(!t||r.settlement_legs)return '';return `<div class="note"><b>Proposed partial settlement</b>${rows([['Seller receives',fmt(t.seller_net)+' MMK'],['Buyer refund',fmt(t.buyer_refund)+' MMK'],['Service fee retained',fmt(t.fee)+' MMK']])}<p>Both participants must agree. Finance then needs independent approval before either transfer is sent.</p>${r.has_split_consent?'<p>Your agreement to this exact allocation is saved.</p>':(r.is_owner||r.is_buyer)?`<form id="split-consent-form"><label class="check"><input name="agree" type="checkbox" required><span>I agree to this exact allocation and retained service fee.</span></label><button class="secondary" type="submit">Agree to this settlement</button></form>`:''}</div>`;}
function timeline(r){if(r.settlement_legs)return settlementSummary(r);if(['refunded','refund_pending'].includes(r.state)||r.instruction_type==='refund'){const complete=r.state==='refunded';return `<div class="timeline"><div class="step done"><span class="node">✓</span><div><b>Payment received</b><small>${fmt(r.total)} MMK · collection confirmed</small></div></div><div class="step done"><span class="node">✓</span><div><b>Refund independently approved</b><small>Original payer source · principal and fee</small></div></div><div class="step ${complete?'done':'current'}"><span class="node">${complete?'✓':'3'}</span><div><b>${complete?'Refund confirmed':'Refund in progress'}</b><small>${complete?fmt(r.total)+' MMK returned to the original simulated source':'No seller payout was made. Staff follow any pending or uncertain result.'}</small></div></div></div>`;}const collected=r.collection==='confirmed',paid=r.state==='completed',refunded=r.state==='refunded';const items=[['Payment received',collected?'Confirmed in the simulator':'Waiting for provider confirmation',collected],r.kind==='escrow'?['Seller delivers',r.state==='held'?'Seller’s next step':r.state==='delivered'?'Buyer checks delivery':'Agreed directly between both parties',['delivered','release_pending','completed'].includes(r.state)]:['Recipient payout',r.payout==='unknown'?'Outcome uncertain · staff is checking':r.payout==='failed'?'Payment received; staff action needed':r.payout==='pending'?'Waiting for confirmation':'Settlement follows collection',paid],r.kind==='escrow'?['Buyer checks the item',r.case_open?'A report has paused release':'Buyer-authorized release only',paid]:['Recipient receives payment',paid?'Confirmed by the simulator':'Collection does not mean recipient paid',paid],...(r.kind==='escrow'?[['Payment releases to '+esc(r.name),refunded?'Refunded to original payer':paid?'Payout confirmed':'Payout confirmation is a separate step',paid||refunded]]:[])];return `<div class="timeline">${items.map(([title,desc,done],i)=>`<div class="step ${done?'done':'current'}"><span class="node">${done?'✓':i+1}</span><div><b>${title}</b><small>${desc}</small></div></div>`).join('')}</div>`;}
function eventReason(e){if(e.type==='command.committed'){const d=JSON.parse(e.reason);return 'Command '+d.action+' · '+d.command_id;}if(e.type==='financial.transition'){const d=JSON.parse(e.reason);return label(d.before.state)+' → '+label(d.after.state)+' · '+fmt(d.net)+' MMK net · '+(d.destination||'');}return e.reason;}
function events(r){return `<div class="event-list">${(r.events||[]).slice().reverse().map(e=>`<div class="event-item"><b>${esc(e.type.replaceAll('.',' · ').replaceAll('_',' '))}</b><small>${date(e.created)} · ${esc(e.actor.startsWith('person-')?'Participant':e.actor)}</small>${e.reason?`<small>${esc(eventReason(e))}</small>`:''}</div>`).join('')}</div>`;}
function detailAside(r){return `<aside class="detail-aside"><h2>Payment details</h2>${rows([['Reference',esc(r.code)],['Recipient',esc(r.name)],[r.settlement_legs?'Seller allocation':r.state==='refunded'?'Recipient received':'Recipient net',fmt(r.settlement_legs?r.settlement_legs.find(x=>x.instruction_type==='payout').net:r.state==='refunded'?0:r.net)+' MMK'],['Customer total',fmt(r.total)+' MMK'],['Fee',fmt(r.fee)+' MMK'],['Collection',esc(r.collection)],['Payout',esc(r.payout)]])}${r.private?`<h2 class="sub">Shared history</h2>${events(r)}`:'<p class="fine">Restore private access to view your full history and participant actions.</p>'}</aside>`;}
function checkout(r){const buyer=r.is_buyer||r.is_payer;app.innerHTML=top('Review · pay · follow')+head(r.kind==='escrow'?'Your protected deal':'Review payment')+backupBanner()+`<section class="flow-card" data-screen-label="Payment review"><h1>${r.kind==='escrow'?'Pay '+fmt(r.net)+' MMK to '+esc(r.name):'A payment for '+esc(r.name)+'.'}</h1>${beneficiary(r)}${r.kind==='escrow'?rows([['Item',esc(r.item)],['Delivery',esc(r.delivery)],['Time to check',esc(r.window)]])+`<p class="sub">${esc(r.description)}</p>`:amount(r.total,'You pay · includes '+fmt(r.fee)+' MMK fee')}${r.kind==='escrow'?`<div class="note">Your payment stays held until you receive and check the item, then authorize release. A report pauses release. The seller’s delivery claim does not start automatic release.</div>`:''}${(buyer||(!r.is_owner&&r.can_join))?`<form id="checkout-form">${!buyer?field("invitation","Private buyer invitation key","","password","required autocomplete=off"):""}${buyer?selectField('method','Payment method',['KPay','WavePay','UAB Pay','AYA Pay'],r.method||'KPay')+rows([['Item / net amount',fmt(r.net)+' MMK'],['Illustrative fee',fmt(r.fee)+' MMK'],['You pay',fmt(r.total)+' MMK']]):''}<label class="check"><input type="checkbox" name="agree" required><span>${buyer?'I reviewed the amount, recipient, fee, and simulated payment.':'I agree to the item, delivery and buyer-authorized release terms. Join this deal as its buyer.'}</span></label>${errorBox()}<div class="actions"><button class="primary" type="submit">${buyer?'Continue to payment simulator ↗':'Accept & continue to pay'}</button>${buyer&&r.quote_expires<Date.now()/1000?button('Refresh expired quote','requote','secondary'):''}</div></form>`:`${errorBox()}<div class="actions">${r.is_owner?link('Share buyer invitation','share/'+r.id,'primary'):link('Restore private access','access','primary')}</div><p class="fine">${r.is_owner?'You are the seller. The buyer joins using their own private session.':'This deal already has a private buyer. A public link cannot act on their behalf.'}</p>`}</section>`;}
function publicEntry(r){if(r.kind==='shop'||r.kind==='request'){if(r.kind==='request'&&r.payment_id&&r.is_owner)return requestOwner(r);app.innerHTML=top('Simple payment acceptance')+head(r.kind==='shop'?'Pay '+esc(r.name):'Payment request')+`<section class="flow-card" data-screen-label="Public payment entry"><h1>${r.kind==='shop'?'A payment for '+esc(r.name)+'.':'You pay. They receive.'}</h1>${beneficiary(r)}${r.kind==='request'?amount(r.total,'Recipient receives '+fmt(r.net)+' MMK'):''}${rows([['Payout destination',esc(r.rail)+' '+esc(r.destination_mask)],['Payment fee',r.kind==='shop'?'2% · minimum 100 MMK · illustrative':fmt(r.fee)+' MMK'],['Settlement','Collection and payout confirmed separately']])}<form id="intent-form">${r.kind==='shop'?field('net','Shop receives · MMK','','number','min="500" max="1000000" step="1" inputmode="numeric" required'):''}${errorBox()}<div class="actions"><button class="primary" type="submit" ${r.state==='expired'||r.paused?'disabled':''}>${r.state==='expired'?'Request expired':r.paused?'Shop payments paused':'Review & pay'}</button>${r.is_owner?link('Share '+(r.kind==='shop'?'shop QR':'request'),'share/'+r.id):''}${r.kind==='shop'&&r.is_owner?button(r.paused?'Resume payments':'Pause new payments','pause','quiet'):''}</div></form><p class="fine">${r.kind==='request'?'One request accepts one payment.':'Every payment receives its own reference.'} Simulated funds only.</p>${r.kind==='shop'&&r.is_owner?`<details class="staff-login"><summary>Update simulated payout setup</summary><p>Existing payments retain their destination. New payments use the next beneficiary version.</p><form id="destination-form">${selectField('rail','New payout route',['KPay','WavePay','UAB Pay','AYA Pay'],r.rail)}${field('destination','New demo destination','','text','required minlength="5" maxlength="30"')}<label class="check"><input name="demo_verified" type="checkbox" required><span>Confirm simulated verification of this destination.</span></label><button class="secondary" type="submit">Save for new payments</button></form></details>`:''}</section>`;return;}checkout(r);}
function requestOwner(r){app.innerHTML=top('Your payment request')+head('Request activity')+`<section class="flow-card"><h1>${esc(r.name)}</h1>${amount(r.net,'You receive')}${rows([['Reference',esc(r.code)],['Customer total',fmt(r.total)+' MMK'],['Payment',label(r.state)]])}<div class="actions">${link('Follow payment','record/'+r.payment_id,'primary')}${link('Share request','share/'+r.id)}</div></section>`;}
function status(r){const refunding=['refunded','refund_pending'].includes(r.state)||r.instruction_type==='refund';const attention=r.case_open||['payout_unknown','payout_failed'].includes(r.state);const success=['completed','refunded','settled'].includes(r.state);const state=success?(refunding?'payment_confirmed':'payout_confirmed'):attention?'needs_attention':r.state==='held'?'payment_confirmed':'waiting';app.innerHTML=top('Every step, together')+head(r.kind==='escrow'?'Your protected deal':'Payment progress')+`<div class="status-layout" data-screen-label="Payment status"><section class="flow-card tint"><div class="hero">${statusMascot(r,state)}${amount(refunding?r.total:r.net,r.settlement_legs?'Original principal':'')}<h1>${label(r.state)}</h1><p>${r.kind==='escrow'?'For '+esc(r.item):'For '+esc(r.name)}<br>${fmt(r.fee)} MMK ${refunding?'service fee included in refund':'service fee separate'}</p></div>${timeline(r)}${splitConsent(r)}${r.case_open?`<div class="note"><b>A person will review this case.</b>${r.evidence_request&&r.private?`<p>Staff request: ${esc(r.evidence_request)}</p>`:''}<p>${r.private?esc(r.case_reason):'Payment progress is being reviewed. Restore participant access for case details.'}</p></div>`:''}${errorBox()}<div class="actions">${r.is_owner&&r.kind==='escrow'&&r.state==='held'?button('I delivered the item','deliver'):r.is_buyer&&r.state==='delivered'?link('Check & authorize release','release/'+r.id,'primary'):success?link('View receipt','receipt/'+r.id,'primary'):button('Check latest status','refresh')}${r.private&&r.kind==='escrow'&&['held','delivered','release_pending'].includes(r.state)?link('Report a problem','report/'+r.id):''}${r.private&&r.case_open?link('Add private case evidence','report/'+r.id):''}${r.state==='collection_pending'&&(r.is_buyer||r.is_payer)?link('Return to payment simulator','provider/'+r.id):''}${session?.role!=='customer'&&session?link('Open staff case','case/'+r.id):''}</div><p class="fine">${r.state==='payout_pending'?'Payment was received. No second payment is needed.':r.state==='release_pending'?'Your authorization is saved. Waiting for confirmed payout.':'Progress is saved on the server and updates automatically.'}</p></section>${detailAside(r)}</div>`;}
function provider(r){if(!r.is_buyer&&!r.is_payer)throw new Error('Restore the private payer session to continue.');app.innerHTML=top('Payment handoff')+head('Continue payment','record/'+r.id)+`<section class="flow-card" data-screen-label="Provider handoff"><div class="simulator-label">Local simulation · no real money</div><h1>${esc(r.method||'Payment')} authorization</h1>${amount(r.total,'You pay')}${beneficiary(r)}<p class="sub">Continue to the separate local provider simulator. Returning here alone does not confirm a payment.</p>${errorBox()}<div class="actions">${r.collection==='pending'?`<a class="primary" href="/simulator.html#${r.id}">Open local provider simulator ↗</a>`:''}${link('View saved payment status','record/'+r.id,'secondary')}</div></section>`;}

function release(r){if(!r.is_buyer||r.state!=='delivered')throw new Error('Only this deal’s private buyer can release a delivered payment.');app.innerHTML=top('Check before you release')+head('Confirm delivery','record/'+r.id)+`<section class="flow-card"><h1>Everything as agreed?</h1>${amount(r.net,'Release to the seller')}${beneficiary(r)}<form id="release-form"><label class="check"><input type="checkbox" name="agree" required><span>I received and checked ${esc(r.item)}. I authorize release to the destination above.</span></label>${errorBox()}<div class="actions"><button class="primary" type="submit">Confirm & release ${fmt(r.net)} MMK</button>${link('Report a problem','report/'+r.id)}</div></form></section>`;}
function report(r){if(!r.private)throw new Error('Restore private participant access to report a problem.');app.innerHTML=top('A person is here to help')+head(r.case_open?'Your private case':'Report a problem','record/'+r.id)+`<section class="flow-card"><h1>${r.case_open?'Let’s work through it.':'Tell us what happened.'}</h1>${r.case_id?`<p class="fine">Case ${esc(r.case_id)}</p>`:''}<p class="sub">${r.case_open?'Your payment has a staff case. Evidence stays private to the participants and staff.':'Submitting a report pauses an unpaid escrow release immediately.'}</p>${splitConsent(r)}${r.case_open?`<div class="note">${esc(r.case_reason)}</div><form id="evidence-form"><label class="field"><span>Add a photo, PDF, or text file · up to 2 MB</span><input name="file" type="file" accept="image/png,image/jpeg,application/pdf,text/plain" required></label>${errorBox()}<div class="actions"><button class="primary" type="submit">Add private evidence</button></div></form><div class="file-list">${(r.evidence||[]).map(x=>`<a href="/api/evidence/${x.id}">${esc(x.name)} ↓</a>`).join('')}</div>`:`<form id="report-form"><label class="field"><span>What went wrong?</span><textarea name="reason" required minlength="8" maxlength="1000" placeholder="Describe the issue for the person reviewing your deal."></textarea></label>${errorBox()}<div class="actions"><button class="primary" type="submit">Submit report & pause release</button></div></form>`}<div class="actions">${link('Back to payment','record/'+r.id)}</div></section>`;}
function receipt(r){if(r.settlement_legs){app.innerHTML=top('Your agreed settlement')+head('Settlement receipt','record/'+r.id)+`<section class="flow-card"><h1>${r.state==='settled'?'Settlement completed.':'Settlement in progress.'}</h1>${amount(r.total,'Original customer payment')}${settlementSummary(r)}${rows([['Original fee',fmt(r.fee)+' MMK'],['Reference',esc(r.code)]])}<p class="fine">Each transfer is confirmed separately. This is a local simulation receipt.</p></section>`;return;}if(!r.private)throw new Error('Restore private participant access to view the receipt.');if(!['completed','refunded','settled'].includes(r.state))return go('record/'+r.id);app.innerHTML=top('A little peace of mind')+head('Your receipt','record/'+r.id)+`<section class="flow-card" data-screen-label="Receipt"><div class="receipt-heading"><span class="avatar">✓</span><h1>${r.state==='refunded'?'Refund confirmed.':'Payment completed.'}</h1></div>${amount(r.total,r.state==='refunded'?'Refunded to original simulated source':'Customer paid')}${rows([['Recipient',esc(r.name)],['Recipient received',r.state==='refunded'?'0 MMK':fmt(r.net)+' MMK'],['Fee',r.state==='refunded'?'Refunded with principal':fmt(r.fee)+' MMK'],['Reference',esc(r.code)],['Collection','Confirmed'],['Payout / refund','Confirmed'],['Destination',r.state==='refunded'?'Original simulated payer':esc(r.rail)+' '+esc(r.destination_mask)]])}<p class="fine">Local simulation receipt. It is not evidence of a real-world payment.</p><div class="actions">${button('Save / print receipt','print')}${r.shop_id?link('Make another shop payment','record/'+r.shop_id):''}${link('Your activity','activity')}</div></section>`;}
async function activity(seq){if(session?.role!=='customer'){access();return;}const d=await api('/api/activity');if(seq!==routeSequence)return;app.innerHTML=top('All in one place')+head('Your activity')+backupBanner()+`<div class="toolbar"><label class="screen-reader" for="activity-search">Search your activity</label><input id="activity-search" placeholder="Search item, recipient, or reference" autocomplete="off"></div><div id="activity-list">${activityRows(d.records)}</div>`;document.getElementById('activity-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.getElementById('activity-list').innerHTML=activityRows(d.records.filter(r=>JSON.stringify([r.item,r.name,r.code,r.state]).toLowerCase().includes(q)));});}
function access(){app.innerHTML=top('Only you can pick up here')+head('Private access')+backupBanner()+`<section class="flow-card"><h1>${session?'Your session is active.':'Pick up where you left off.'}</h1><p class="sub">A private session keeps your activity and participant actions yours. Your public payment code does not unlock it.</p>${session?rows([['Session',session.role==='customer'?'Customer':esc(session.actor)],['Access',session.role==='customer'?'This browser only · restore elsewhere with your key':'Staff · '+esc(session.role)]])+`<div class="actions">${link('Open '+(session.role==='customer'?'activity':'staff workspace'),session.role==='customer'?'activity':'admin','primary')}${button('Sign out of this browser','logout','secondary')}</div>`:`<form id="recover-form">${field('recovery','Private recovery key','','password','required autocomplete="off"')}${errorBox()}<div class="actions"><button class="primary" type="submit">Restore private access</button>${button('Start a new private session','new-session','secondary')}</div></form>`}<p class="fine">New sessions receive a private recovery key once. Save it before leaving. Recovery delivery by SMS/email is not connected.</p><div class="actions">${link('Staff sign-in','admin')}</div></section>`;}
function codeEntry(){app.innerHTML=top('A shorter way there')+head('Enter a code')+`<section class="flow-card"><h1>A short code.<br>The same payment.</h1><form id="code-form">${field('code','Deal, request, or shop code','','text','required placeholder="HS-1234ABCD" autocomplete="off"')}${errorBox()}<div class="actions"><button class="primary" type="submit">Open payment page</button></div></form><p class="fine">This opens a public page. It cannot release funds, change a payout destination, or restore private access.</p></section>`;}
function staffLogin(){app.innerHTML=top('Operations, together')+head('Staff workspace')+`<section class="flow-card"><h1>The right access.<br>The right action.</h1>${session?'<div class="note">Sign out of the customer session to sign in as staff. Use a separate browser to keep both sessions open.</div>':''}<form id="staff-form">${selectField('username','Staff identity',['support','operations','finance-a','finance-b','admin'],'support')}${field('password','Local staff password','','password','required autocomplete="current-password"')}${errorBox()}<div class="actions">${session?button('Sign out of customer session','logout','secondary'):'<button class="primary" type="submit">Sign in to staff workspace</button>'}</div></form><details class="staff-login"><summary>Local demo sign-in</summary><p>Password: <b>handshake-demo-2026</b> unless overridden when starting the server. Finance A and Finance B are separate approvers. No live payment tools are connected.</p></details></section>`;}
async function admin(seq){if(!session||session.role==='customer')return staffLogin();const d=await api('/api/admin');if(seq!==routeSequence)return;adminData=d;app.innerHTML=top('Staff · '+esc(session.actor))+`<div class="section-heading"><h1>Make the next step clear.</h1><a class="pill" href="#access">Sign out ↗</a></div><p class="sub">Resolve cases, follow both payment legs, and keep the record straight.</p><div class="staff-grid"><section class="staff-card"><span class="eyebrow">Needs attention</span><div class="balance">${d.records.filter(r=>r.case_open).length}</div><p class="fine">Open cases across both services</p></section><section class="staff-card"><span class="eyebrow">Simulated payout float</span><div class="balance">${fmt(d.float)} <small>MMK</small></div><p class="fine">Available after pending and uncertain reservations</p></section></div><section class="staff-card"><div class="toolbar"><label class="screen-reader" for="staff-search">Search transactions</label><input id="staff-search" placeholder="Search reference, recipient, item" value="${esc(search)}"><label class="screen-reader" for="staff-filter">Queue filter</label><select id="staff-filter"><option value="attention" ${adminFilter==='attention'?'selected':''}>Needs attention</option><option value="all" ${adminFilter==='all'?'selected':''}>All records</option><option value="escrow" ${adminFilter==='escrow'?'selected':''}>Escrow</option><option value="shop" ${adminFilter==='shop'?'selected':''}>Shops</option></select></div><div class="toolbar queue-filters">${selectField('queueAssignee','Assignee',['Any assignee','support','operations','finance-a','finance-b','admin'],queueAssignee||'Any assignee')}${field('queueMinAmount','Minimum net · MMK',queueMinAmount,'number','min="0" step="1"')}${field('queueAge','Minimum age · hours',queueAge,'number','min="0" step="1"')}</div><div id="staff-list">${adminRows()}</div></section><div class="staff-grid"><section class="staff-card"><h2>Reconciliation</h2><p class="sub">Local adapter receipts compared with the ledger. Each journal must balance to zero.</p>${rows(d.balances.map(x=>[esc(x.account.replaceAll('_',' ')),fmt(x.balance)+' MMK']))}<div class="note">${d.differences.length?d.differences.length+' differences need investigation.':'No differences in local receipts or journal balances.'}</div><div class="actions">${button('Export reconciliation CSV','export-ledger','secondary')}</div></section><section class="staff-card"><h2>Collection routes</h2><p class="sub">KPay, WavePay, UAB Pay and AYA Pay are simulated. Existing liabilities remain when collections pause.</p><div class="note">New collections: <b>${d.route_open?'Open':'Paused'}</b></div>${session.role!=='support'?`<form id="route-form">${field('reason','Reason for availability change','','text','required minlength="8"')}<div class="actions"><button class="secondary" type="submit">${d.route_open?'Pause':'Resume'} new collections</button></div></form>`:''}</section></div><section class="staff-card"><h2>Provider receipt inbox</h2><p class="fine">Authenticated extra and mismatched receipts have separate refund-only cases. Rejected or unmatched deliveries remain visible for investigation.</p>${(d.inbox||[]).filter(x=>!['matched','duplicate'].includes(x.disposition)).slice(0,20).map(x=>`<div class="event-item"><b>${esc(x.disposition)} · ${esc(x.receipt_id)}</b><small>${esc(x.reason)}</small>${x.recovery_id?link('Open refund-only recovery case','case/'+x.recovery_id):`<small>Provider reference needs investigation; no fulfillment was invented.</small>`}</div>`).join('')||'<p>No receipt exceptions.</p>'}</section><section class="staff-card"><div class="section-heading"><h2>Audit history</h2>${button('Export CSV','export-audit','pill')}</div>${events({events:d.audit.slice().reverse().slice(-30)})}</section>`;app.querySelector('.queue-filters').addEventListener('input',e=>{if(e.target.name==='queueAssignee')queueAssignee=e.target.value==='Any assignee'?'':e.target.value;if(e.target.name==='queueMinAmount')queueMinAmount=Number(e.target.value);if(e.target.name==='queueAge')queueAge=Number(e.target.value);document.getElementById('staff-list').innerHTML=adminRows();});document.getElementById('staff-search').addEventListener('input',e=>{search=e.target.value;document.getElementById('staff-list').innerHTML=adminRows();});document.getElementById('staff-filter').addEventListener('change',e=>{adminFilter=e.target.value;document.getElementById('staff-list').innerHTML=adminRows();});}
function adminRows(){const records=adminData.records.filter(r=>(adminFilter==='all'||adminFilter==='attention'&&r.case_open||r.kind===adminFilter)&&(!queueAssignee||r.assignee===queueAssignee)&&(!queueMinAmount||r.net>=queueMinAmount)&&(!queueAge||Date.now()/1000-r.created>=queueAge*3600)&&JSON.stringify([r.name,r.item,r.code,r.id,r.state,r.collection_reference,r.jobs]).toLowerCase().includes(search.toLowerCase()));return records.length?records.map(r=>`<a class="activity-row" href="#case/${r.id}"><span class="avatar">${r.case_open?'!':r.kind==='escrow'?'↔':'↗'}</span><span><b>${esc(r.item||r.name)}</b><small>${esc(r.code)} · ${date(r.created)}</small></span><span class="right"><b>${r.net?fmt(r.net)+' MMK':'Shop'}</b><small>${label(r.state)}</small></span></a>`).join(''):'<div class="empty"><h3>No matching records.</h3><p>Open cases appear here as soon as the server records them.</p></div>';}
function staffCase(r){if(!session||session.role==='customer')return staffLogin();const proposal=(r.proposals||[]).find(p=>['proposed','approved'].includes(p.state));app.innerHTML=top('Staff case · '+esc(r.code))+head(esc(r.item||r.name),'admin')+`<div class="status-layout"><section class="flow-card"><span class="badge ${r.case_open?'attention':''}">${label(r.state)}</span>${amount(r.net,'Principal / recipient net')}${beneficiary(r)}${rows([['Collection',esc(r.collection)],['Payout',esc(r.payout)],['Customer total',fmt(r.total)+' MMK'],['Open case',r.case_open?'Yes':'No']])}${r.case_reason?`<div class="note">${esc(r.case_reason)}</div>`:''}${settlementSummary(r)}${r.split_terms?`<div class="note">Seller ${fmt(r.split_terms.seller_net)} MMK · buyer refund ${fmt(r.split_terms.buyer_refund)} MMK · fee ${fmt(r.split_terms.fee)} MMK<br>${(r.split_consents||[]).length} of 2 participant agreements saved.</div>`:''}<form id="staff-action-form">${field('reason','Reason / review note','','text','required minlength="8" maxlength="1000"')}${errorBox()}<div class="actions">${button('Add case note','staff-note','secondary')}${r.kind==='escrow'&&['held','delivered','release_pending'].includes(r.state)?button('Pause held release','staff-pause-release','secondary'):''}${selectField('assignee','Assign to',['support','operations','finance-a','finance-b','admin'],r.assignee||'support')}${button('Assign case','staff-assign','secondary')}${r.case_open?button('Request evidence from participants','staff-request-evidence','secondary'):''}${r.case_open&&canFinance()&&!r.settlement_legs?button('Record human review','staff-review','secondary'):''}${r.kind==='escrow'&&r.case_open&&canFinance()&&!r.settlement_legs&&!proposal?field('seller_net','Seller allocation · MMK',r.split_terms?.seller_net||'','number','min=1 step=1')+button('Offer partial settlement','staff-offer-split','secondary'):''}${r.payout==='unknown'&&!r.settlement_legs?button('Query existing provider reference','staff-query','secondary'):''}${r.case_open&&canFinance()&&!proposal&&!r.settlement_legs?`${selectField('decision','Proposed instruction',r.recovery_only?['refund','retry']:r.kind==='escrow'?['refund','release','retry','split']:['refund','retry'],'refund')}${button('Propose instruction','staff-propose')}`:''}${proposal?`${canFinance()?button('Cancel pending proposal','staff-cancel','quiet'):''}<div class="note"><b>${esc(proposal.action)} · ${fmt(proposal.amount)} MMK</b><br>Proposed by ${esc(proposal.proposer)} · ${esc(proposal.state)}<br>${esc(proposal.reason)}<br>Destination: ${proposal.action==='refund'?'original '+esc(r.method||'payment')+' payer source':esc(r.rail)+' '+esc(r.destination_mask)}</div>${proposal.state==='proposed'&&canFinance()?button('Independently approve instruction','staff-approve','primary',`data-proposal="${proposal.id}"`):proposal.state==='approved'&&session.role!=='support'?button('Submit approved instruction','staff-submit','primary',`data-proposal="${proposal.id}"`):''}`:''}</div></form>${r.kind==='shop'?`<p class="fine">Shop pause is controlled from the private owner page. Staff can pause the shared collection route in the workspace.</p>`:''}<div class="file-list">${(r.evidence||[]).map(x=>`<a href="/api/evidence/${x.id}">${esc(x.name)} ↓</a>`).join('')}</div><div class="actions">${link('Open participant status','record/'+r.id)}</div></section><aside class="detail-aside"><h2>Shared event history</h2>${events(r)}${canFinance()?`<details class="staff-login"><summary>Provider simulation lab</summary><p>These controls change deterministic local provider results. They cannot move real funds.</p><form id="scenario-form">${selectField('scenario','Provider outcome',['success','payout_failed','payout_unknown','insufficient_float'],r.scenario||'success')}${field('reason','Simulation reason','','text','required minlength="8"')}<div class="actions"><button class="secondary" type="submit">Set simulation scenario</button></div></form></details>`:''}</aside></div>`;}
function help(){app.innerHTML=top('A little more clarity')+head('How Handshake works')+`<article class="help"><h1>Two services.<br>One place to follow them.</h1><h2>Protect a deal</h2><ol><li>The seller records the item, delivery terms, amount, and payout destination.</li><li>The buyer opens the link in their own browser session and accepts the agreement.</li><li>A confirmed simulated payment is held while the seller delivers.</li><li>The buyer checks the delivery and authorizes release, or reports a problem.</li><li>Recipient-paid appears only after a separate payout confirmation.</li></ol><h2>Accept payments</h2><p>Create a single-use request, or set up a shop with a permanent QR. Customers review the net amount, fee, destination, and their own total before continuing. Each shop payment is a separate record.</p><h2>Your private access</h2><p>New customer sessions get a private recovery key. Save it to restore the same activity in another browser. Public payment links and short codes open the payment page; they do not grant participant or owner authority.</p><h2>Try the complete product locally</h2><p>Use a regular browser for the seller and a private browser window for the buyer. For staff cases, use the staff workspace. Two finance identities are required to approve an exceptional payout or refund.</p><div class="note">This app runs locally with persistent server records and a payment simulator. Live collection, escrow custody, real account verification, bank settlement, and SMS/email delivery are not connected. Local QR links work only on this computer.</div><div class="actions">${link('Create your first deal','create/escrow','primary')}${link('Open staff workspace','admin')}</div></article>`;}
async function render(){const seq=++routeSequence;clearTimeout(poll);const [route='home',id]=(location.hash.slice(1)||'home').split('/');current=null;document.title='Handshake · '+({home:'Home',activity:'Your activity',admin:'Staff workspace',create:'Create',record:'Payment',share:'Share'}[route]||'Your next step');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));try{const latestSession=await api('/api/session');if(seq!==routeSequence)return;session=latestSession.session;if(route==='home'||!route)await home(seq);else if(route==='create'){await customer();const saved=await api('/api/drafts');if(seq!==routeSequence)return;if(saved.drafts[id])localStorage.setItem('handshake-draft-'+id,JSON.stringify(saved.drafts[id]));create(id);}else if(route==='review')review();else if(route==='activity')await activity(seq);else if(route==='access')access();else if(route==='code')codeEntry();else if(route==='help')help();else if(route==='admin')await admin(seq);else if(['record','share','provider','release','report','receipt','case'].includes(route)){const {record:r}=await api('/api/records/'+encodeURIComponent(id));if(seq!==routeSequence)return;current=r;if(route==='share'){if(!r.is_owner)throw new Error('Restore the private owner session to share from your activity.');share(r);}else if(route==='provider')provider(r);else if(route==='release')release(r);else if(route==='report')report(r);else if(route==='receipt')receipt(r);else if(route==='case')staffCase(r);else if(['escrow','payment'].includes(r.kind)&&!['awaiting_buyer','awaiting_payment','payment_failed'].includes(r.state))status(r);else publicEntry(r);if(route==='record'&&r.kind!=='shop'&&(r.kind!=='request'||r.is_owner&&r.payment_id)&&!['awaiting_buyer','awaiting_payment','payment_failed','completed','refunded','settled'].includes(r.state))schedulePoll(id,r.version,r.state);}else throw new Error('This page is unavailable. Start from Home.');document.querySelectorAll('soft-elephant').forEach(el=>{if(reduceMotion)el.setReducedMotion(true);});}catch(e){if(seq!==routeSequence)return;app.innerHTML=top('Let’s pick up here')+head('One moment')+`<section class="flow-card"><h1>There’s a next step.</h1><div class="error" role="alert">${esc(e.message)}</div><div class="actions">${link('Restore private access','access','primary')}${link('Go home','home')}</div></section>`;}}
function schedulePoll(id,version,state){poll=setTimeout(async()=>{try{const d=await api('/api/records/'+id);if(location.hash!=='#record/'+id)return;if(d.record.version!==version||d.record.state!==state)render();else schedulePoll(id,version,state);}catch{toast('Connection interrupted. Your saved payment remains on the server.');schedulePoll(id,version,state);}},2000);}
async function command(action,body={}){const result=await api('/api/records/'+current.id+'/'+action,{...body,command_id:key(),expected_version:current.version});current=result.record;return current;}
function formObject(form){return Object.fromEntries(new FormData(form));}
async function run(work){if(busy)return;busy=true;const buttons=[...app.querySelectorAll('button')];buttons.forEach(b=>{b.dataset.wasDisabled=b.disabled?'yes':'no';b.disabled=true;});try{await work();}catch(e){showError(e.message);}finally{busy=false;buttons.filter(b=>b.isConnected).forEach(b=>b.disabled=b.dataset.wasDisabled==='yes');}}
document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();run(async()=>{const b=formObject(form);switch(form.id){case 'create-form':clearTimeout(draftTimer);createDraft={...b,kind:form.dataset.kind,net:Number(b.net),demo_verified:!!b.demo_verified,command_id:key()};await api('/api/drafts',createDraft);sessionStorage.setItem('handshake-review-draft',JSON.stringify(createDraft));localStorage.setItem('handshake-draft-'+createDraft.kind,JSON.stringify(createDraft));go('review');break;case 'checkout-form':await customer();if(current.can_join){await command('join',{agree:true,invitation:b.invitation});go('record/'+current.id);}else{await command('authorize',{method:b.method,agree:true});go('provider/'+current.id);}break;case 'intent-form':await customer();{const result=await command('pay-intent',{net:Number(b.net)});go('record/'+result.id);}break;case 'release-form':await command('release',{agree:true});go('record/'+current.id);break;case 'report-form':await command('dispute',{reason:b.reason});go('record/'+current.id);break;case 'code-form':{const r=await api('/api/resolve?code='+encodeURIComponent(b.code));go('record/'+r.id);}break;case 'recover-form':{const r=await api('/api/session/recover',b);session=r.session;go('activity');toast('Your private activity is restored.');}break;case 'staff-form':{const r=await api('/api/session/staff',b);session=r.session;go('admin');}break;case 'split-consent-form':await command('consent-split',{agree:true,split_hash:current.split_terms.hash});render();break;case 'destination-form':await command('destination',{...b,demo_verified:!!b.demo_verified});toast('New payments use the updated destination. Existing quotes keep their original destination.');render();break;case 'scenario-form':await command('scenario',{scenario:b.scenario,reason:b.reason});toast('Simulation scenario saved.');render();break;case 'route-form':await api('/api/admin/route',{open:!adminData.route_open,reason:b.reason});render();break;case 'evidence-form':{const file=form.elements.file.files[0];if(file.size>2*1024*1024)throw new Error('Choose a file no larger than 2 MB.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await command('evidence',{name:file.name,mime:file.type||'text/plain',content});toast('Private evidence saved.');render();}break;}});});
document.addEventListener('input',e=>{const form=e.target.closest('#create-form');if(form){const d=formObject(form);d.kind=form.dataset.kind;localStorage.setItem('handshake-draft-'+d.kind,JSON.stringify(d));clearTimeout(draftTimer);draftTimer=setTimeout(()=>api('/api/drafts',d).catch(()=>toast('Draft remains on this browser. Server save will resume when connected.')),350);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;run(async()=>{const action=b.dataset.action;if(action==='create-confirm'){await customer();const {record}=await api('/api/create',{...createDraft,command_id:createDraft.command_id||key()});localStorage.removeItem('handshake-draft-'+createDraft.kind);sessionStorage.removeItem('handshake-review-draft');createDraft=null;go('share/'+record.id);}else if(action==='new-session'){await customer();go('home');}else if(action==='logout'){clearTimeout(draftTimer);createDraft=null;sessionStorage.removeItem('handshake-review-draft');for(const kind of ['escrow','request','shop'])localStorage.removeItem('handshake-draft-'+kind);await api('/api/session/logout',{});session=null;backup='';sessionStorage.removeItem('handshake-new-recovery');go('home');}else if(action==='dismiss-backup'){backup='';sessionStorage.removeItem('handshake-new-recovery');render();}else if(action==='download-key'){download('Handshake private recovery.txt','Handshake private recovery key\n\n'+backup+'\n\nKeep this private. Open Handshake > Private access to restore your activity.');}else if(action==='copy'){try{await navigator.clipboard.writeText(b.dataset.value);toast('Public link copied.');}catch{toast('Select and copy the visible public link.');}}else if(action==='refresh'){await render();toast('Latest server status loaded.');}else if(action==='requote'){await command('requote');render();}else if(action==='deliver'){await command('deliver');render();}else if(action==='pause'){await command('pause');render();}else if(action.startsWith('sim-')){const outcome={'sim-confirm':'confirmed','sim-pending':'pending','sim-fail':'failed'}[action];const d=await api('/api/simulate/'+current.id,{outcome});go('record/'+d.record.id);}else if(action==='print')window.print();else if(action.startsWith('staff-')){const form=document.getElementById('staff-action-form');if(!form.reportValidity())return;const values=formObject(form);await command(action.slice(6),{reason:values.reason,decision:values.decision,assignee:values.assignee,seller_net:Number(values.seller_net),proposal:b.dataset.proposal});toast('Staff action recorded.');render();}else if(action==='export-ledger'){download('Handshake reconciliation.csv','Account,Balance MMK\n'+adminData.balances.map(x=>csv(x.account)+','+x.balance).join('\n')+'\n\nJournal differences,'+adminData.differences.length,'text/csv');}else if(action==='export-audit'){download('Handshake audit.csv','Event ID,Time,Record,Actor,Action,Reason\n'+adminData.audit.map(x=>[x.id,date(x.created),x.record_id,x.actor,x.type,x.reason].map(csv).join(',')).join('\n'),'text/csv');}});});
function csv(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
addEventListener('hashchange',async()=>{await render();window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true});});
api('/api/session').then(d=>{session=d.session;render();}).catch(e=>{app.innerHTML=`<div class="error">${esc(e.message)} Reload to reconnect.</div>`;});
})();
